  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_ART_ACA`,`ID_VA_ACA`)
);
ALTER TABLE `fza_articulos_conjuntos_asign` ADD INDEX `IDX_ACA_CONJUNTO` (`CODIGO_ART_ACA`, `ID_AC_ACA`);

