-- Tabla: fza_bancos

DROP TABLE IF EXISTS `fza_bancos`;
CREATE TABLE `fza_bancos` (
  `CODIGO_BAN` varchar(4) NOT NULL COMMENT 'Codigo de entidad NRBE de 4 digitos',
  `NOMBRE_BAN` varchar(100) NOT NULL,
  `BIC_BAN` varchar(11) NULL DEFAULT NULL COMMENT 'BIC/SWIFT de la oficina central (8 u 11)',
