  `ESDIVISA_FORMA_PAGO_CFP` varchar(1) NOT NULL,
  `ESDEVUELVE_CAMBIO_FORMA_PAGO_CFP` varchar(1) NULL DEFAULT 'S' COMMENT 'S=Permite dar cambio. N=No permite (el bono debe gastarse entero o se pierde el resto)',
  `ESABRE_CAJON_FORMA_PAGO_CFP` varchar(1) NULL DEFAULT 'N' COMMENT 'S=Lanza la secuencia de apertura de cajón',
  `ESACTIVO_FORMA_PAGO_CFP` varchar(1) NULL DEFAULT 'S',
  `PORCENTAJE_COMISION_FORMA_PAGO_CFP` int(11) NULL DEFAULT NULL,
  `ESCOMISION_INCL_FORMA_PAGO_CFP` varchar(1) NULL DEFAULT NULL,
  `NUM_COD_DIGIT_FORMA_PAGO_CFP` varchar(1) NULL DEFAULT NULL,
  `ORDEN_VISUAL_FORMA_PAGO_CFP` int(11) NULL DEFAULT '99' COMMENT 'Para ordenar los botones en la pantalla F12',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_FP_CFP`)
);

