CREATE TABLE `fza_empresas_series` (
  `CODIGO_SERIE_EMPSER` varchar(10) NOT NULL,
  `CODIGO_EMP_EMPSER` varchar(10) NOT NULL,
  `CODIGO_ALM_EMPSER` varchar(10) NULL DEFAULT NULL,
  `CODIGO_CAJA_EMPSER` varchar(10) NULL DEFAULT NULL,
  `EMPSER` varchar(12) NOT NULL,
  `TIPO_DOC_EMPSER` varchar(2) NULL DEFAULT NULL,
  `SUBTIPO_EMPSER` varchar(20) NULL DEFAULT NULL,
  `FECHA_DESDE_EMPSER` date NULL DEFAULT NULL,
  `FECHA_HASTA_EMPSER` date NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_SERIE_EMPSER`)
);
ALTER TABLE `fza_empresas_series` ADD INDEX `IDX_EMPSER_EMP_TIPO_FECHA` (`CODIGO_EMP_EMPSER`, `TIPO_DOC_EMPSER`, `FECHA_DESDE_EMPSER`);

