  `CODIGO_GENERADOR_PROCESO_GP` varchar(20) NOT NULL,
  `NOMBRE_GENERADOR_PROCESO_GP` varchar(100) NULL DEFAULT NULL,
  `PROCESO_GENERADOR_PROCESO_GP` text NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
