SELECT `fza_empresas`.`CODIGO_EMP_EMP`                AS `CODIGO_EMP_EMP`,
       `fza_empresas`.`ORDEN_EMP`                     AS `ORDEN_EMP`,
       `fza_empresas`.`ESACTIVO_EMP`                  AS `ESACTIVO_EMP`,
