-- Tabla: fza_inventarios

DROP TABLE IF EXISTS `fza_inventarios`;
CREATE TABLE `fza_inventarios` (
  `CODIGO_EMP_INV` varchar(10) NOT NULL,
  `CODIGO_ALM_INV` varchar(10) NOT NULL,
  `SERIE_INV` varchar(20) NOT NULL,
  `NUMERO_INV` varchar(20) NOT NULL,
  `TIPO_DOC_INV` varchar(5) NOT NULL DEFAULT 'IN',
  `FECHA_INV` datetime NOT NULL,
  `ESTADO_INV` varchar(20) NOT NULL DEFAULT 'ABIERTO' COMMENT 'ABIERTO, CERRADO, APLICADO, CANCELADO',
  `DESCRIPCION_INV` varchar(200) NULL DEFAULT NULL,
  `OBSERVACIONES_INV` text NULL DEFAULT NULL,
  `TOTAL_UNIDADES_DIFERENCIA_INV` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'Suma total de unidades de descuadre',
  `TOTAL_EUROS_DIFERENCIA_INV` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'Variación económica total (apreciación/depreciación global)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ESRECUENTO_REMOTO_INV` char(1) NOT NULL DEFAULT 'N',
  `INSTANTE_ENVIO_RECUENTO_INV` datetime NULL DEFAULT NULL,
  `INSTANTE_RECOGIDA_RECUENTO_INV` datetime NULL DEFAULT NULL,
  `ID_RECUENTO_REMOTO_INV` varchar(40) NULL DEFAULT NULL,
  PRIMARY KEY (`CODIGO_EMP_INV`,`CODIGO_ALM_INV`,`SERIE_INV`,`NUMERO_INV`)
);
