-- Tabla: fza_movimientos_almacen

DROP TABLE IF EXISTS `fza_movimientos_almacen`;
CREATE TABLE `fza_movimientos_almacen` (
  `NUMERO_MOV` varchar(20) NOT NULL,
  `TIPO_DOC_MOV` varchar(5) NOT NULL COMMENT 'VE, TR, AT, AL, IN, AC, AE',
  `SERIE_DOC_MOV` varchar(20) NOT NULL,
  `NUMERO_DOC_MOV` varchar(20) NOT NULL,
  `LINEA_MOV` varchar(4) NOT NULL COMMENT 'Ahora es VARCHAR(4) según libro de estilo',
  `CODIGO_EMP_MOV` varchar(20) NOT NULL,
  `CODIGO_ALM_MOV` varchar(10) NOT NULL,
  `FECHA_MOV` datetime NULL DEFAULT NULL,
  `CODIGO_ART_MOV` varchar(20) NULL DEFAULT NULL COMMENT 'Código Padre (ej: 003)',
  `CODIGO_UNIDAD_MOV` varchar(50) NOT NULL COMMENT 'SKU (ej: 003BLANCO45)',
  `DESCRIPCION_ARTICULO_MOV` varchar(100) NULL DEFAULT NULL,
  `TIPO_MOV` varchar(1) NOT NULL COMMENT 'E = Entrada, S = Salida',
  `CANTIDAD_MOV` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_COSTE_UNITARIO_MOV` decimal(19,6) NULL DEFAULT '0.000000',
  `TOTAL_COSTE_MOV` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'Cantidad * Coste Unitario',
  `PRECIO_MEDIO_MOV` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'PMP capturado en el momento de la transacción',
  `CODIGO_ALM_CONTRA_MOV` varchar(10) NULL DEFAULT NULL COMMENT 'Para traspasos: a qué almacén va',
  `CODIGO_CLI_MOV` varchar(20) NULL DEFAULT NULL COMMENT 'Para ventas o depósitos',
  `CODIGO_PRV_MOV` varchar(20) NULL DEFAULT NULL COMMENT 'Para entradas de compra',
  `ESACTIVO_MOV` varchar(1) NULL DEFAULT 'S',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `TIPO_DOC_REF_MOV` varchar(5) NULL DEFAULT NULL,
  `SERIE_DOC_REF_MOV` varchar(20) NULL DEFAULT NULL,
  `NUMERO_DOC_REF_MOV` varchar(20) NULL DEFAULT NULL,
  `LINEA_REF_MOV` varchar(4) NULL DEFAULT NULL,
  `LOTE_MOV` varchar(50) NULL DEFAULT '' COMMENT 'Número de lote impreso',
  `FECHA_CADUCIDAD_MOV` date NULL DEFAULT NULL,
  `CODIGO_ALM_DOC_MOV` varchar(10) NULL DEFAULT NULL COMMENT 'Almacén/Tienda donde se originó el ticket/operación',
  `NUMERO_OPERACION_DOC_MOV` varchar(20) NULL DEFAULT NULL COMMENT 'Número de operación de caja que causó el movimiento',
  `CODIGO_CAJA_DOC_MOV` varchar(10) NULL DEFAULT NULL COMMENT 'Código de caja donde se originó la operación',
  PRIMARY KEY (`NUMERO_MOV`)
);
ALTER TABLE `fza_movimientos_almacen` ADD INDEX `IDX_FECHA_MOV` (`FECHA_MOV`);
ALTER TABLE `fza_movimientos_almacen` ADD INDEX `IDX_MOV_ALMACEN_FECHA` (`CODIGO_ALM_MOV`, `FECHA_MOV`);
ALTER TABLE `fza_movimientos_almacen` ADD INDEX `IDX_MOV_ART_ALM` (`CODIGO_ART_MOV`, `CODIGO_ALM_MOV`);
