  `CODIGO_FAM_PEDCLIN` varchar(20) NULL DEFAULT NULL,
  `NOMBRE_FAM_PEDCLIN` varchar(200) NULL DEFAULT NULL,
  `COLOR_TEXTO_PEDCLIN` varchar(100) NULL DEFAULT NULL COMMENT 'Texto libre del color del articulo del proveedor',
  `DESCRIPCION_ARTICULO_PEDCLIN` varchar(100) NULL DEFAULT NULL,
  `TIPO_CANTIDAD_ARTICULO_PEDCLIN` varchar(20) NULL DEFAULT 'Uds',
  `CANTIDAD_PEDCLIN` decimal(19,6) NULL DEFAULT '1.000000' COMMENT 'Cantidad PEDIDA por el cliente',
  `CANTIDAD_RECIBIDA_PEDCLIN` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'Suma de cantidades ya albaraneadas (acumulado)',
  `TOTAL_UNIDADES_PEDCLIN` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'SUM(CANTIDAD) celdas pedidas cuando hay pivote',
  `TIPO_IVA_ARTICULO_PEDCLIN` varchar(2) NULL DEFAULT 'N',
  `PORCENTAJE_IVA_PEDCLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_COMPRA_SIVA_ARTICULO_PEDCLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_COMPRA_CIVA_ARTICULO_PEDCLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `TOTAL_PEDCLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `CODIGO_ALMACEN_PEDCLIN` varchar(10) NULL DEFAULT NULL COMMENT 'Almacen destino de la linea — un pedido puede agrupar varios',
  `REF_PRV_PEDCLIN` varchar(50) NULL DEFAULT NULL,
  `DESCRIPCION_VARIACION_PEDCLIN` varchar(200) NULL DEFAULT NULL,
  `FECHA_ENTREGA_PEDCLIN` date NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`NUMERO_PEDC_PEDCLIN`,`SERIE_PEDC_PEDCLIN`,`LINEA_PEDCLIN`)
);
ALTER TABLE `fza_pedidos_compra_lineas` ADD INDEX `IDX_PEDCLIN_ALMACEN` (`CODIGO_ALMACEN_PEDCLIN`);
ALTER TABLE `fza_pedidos_compra_lineas` ADD INDEX `IDX_PEDCLIN_ARTICULO` (`CODIGO_ART_PEDCLIN`);

