-- Tabla: fza_pedidos_lineas

DROP TABLE IF EXISTS `fza_pedidos_lineas`;
CREATE TABLE `fza_pedidos_lineas` (
  `NUMERO_PED_PEDLIN` varchar(12) NOT NULL,
  `SERIE_PED_PEDLIN` varchar(12) NOT NULL,
  `LINEA_PEDLIN` varchar(3) NOT NULL,
  `IDLINEAPS_PEDLIN` varchar(12) NULL DEFAULT NULL,
  `IDPRODPS_PEDLIN` varchar(20) NULL DEFAULT NULL,
  `CODIGOPRODPS_PEDLIN` varchar(200) NULL DEFAULT NULL,
  `IDATRIBPRODPS_PEDLIN` varchar(20) NULL DEFAULT NULL,
  `CODBAR_ART_PEDLIN` varchar(20) NULL DEFAULT NULL,
  `CODIGO_ART_PEDLIN` varchar(20) NULL DEFAULT NULL,
  `CODIGO_FAM_PEDLIN` varchar(10) NULL DEFAULT NULL,
  `NOMBRE_FAM_PEDLIN` varchar(150) NULL DEFAULT NULL,
  `FECHA_ENTREGA_PEDLIN` datetime NULL DEFAULT NULL,
  `TIPO_CANTIDAD_ARTICULO_PEDLIN` varchar(20) NULL DEFAULT 'Uds',
  `ESIMP_INCL_TARIFA_PEDLIN` varchar(1) NULL DEFAULT 'S',
  `TIPO_IVA_ARTICULO_PEDLIN` varchar(2) NULL DEFAULT 'N',
  `DESCRIPCION_ARTICULO_PEDLIN` varchar(100) NULL DEFAULT NULL,
  `CODIGO_TAR_PEDLIN` varchar(10) NULL DEFAULT NULL,
  `CANTIDAD_PEDLIN` decimal(19,6) NULL DEFAULT '1.000000',
  `CANTIDAD_ENTREGADA_PEDLIN` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'Total entregado acumulado de la línea',
  `CANTIDAD_PENDIENTE_PEDLIN` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'Cantidad - entregada (campo calculado para reportes)',
  `ESENTREGADA_PEDLIN` varchar(1) NULL DEFAULT 'N' COMMENT 'S si pendiente=0',
  `CODIGO_ALMACEN_PEDLIN` varchar(10) NULL DEFAULT NULL,
  `PRECIO_VENTA_SIVA_ARTICULO_PEDLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `PORCENTAJE_IVA_PEDLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_VENTA_CIVA_ARTICULO_PEDLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `TOTAL_PEDLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`NUMERO_PED_PEDLIN`,`SERIE_PED_PEDLIN`,`LINEA_PEDLIN`)
);
ALTER TABLE `fza_pedidos_lineas` ADD INDEX `IDX_PEDLIN_ARTICULO` (`CODIGO_ART_PEDLIN`);
ALTER TABLE `fza_pedidos_lineas` ADD INDEX `IDX_PEDLIN_PENDIENTE` (`ESENTREGADA_PEDLIN`);

